        "a2": CheckGuide(proves: "The Home Screen shows the right name and the scooter icon.",
                         steps: ["Go to the Home Screen.", "Look at the icon and the name under it.", "Tap Pass or Fail."], place: .noScooter),
        "a7": CheckGuide(proves: "\"v1\" is visible inside the app on every screen.",
