        "a3": CheckGuide(proves: "The app keeps its permanent ID, so updates keep your data.",
                         steps: ["Nothing to do: it marks itself at every launch."], place: .noScooter),
        "a4": CheckGuide(proves: "Installing a new build over the old one keeps all data.",
                         steps: ["Before installing: Settings → Data and backup → Export everything (save it to Files).",
                                 "In SideStore, install the new .ipa over the existing app (don't delete the app).",
                                 "Open CorckieApp: the check marks itself."], place: .noScooter),
        "a5": CheckGuide(proves: "SideStore renews the 7-day signing by itself.",
