        "a9": CheckGuide(proves: "Nothing was lost in an update: every table has at least as many rows after the update as before.",
                         steps: ["Before installing: Settings → Data and backup → Export everything (save it to Files).",
                                 "Install the new .ipa over the old app in SideStore (never delete the old app first), then open CorckieApp.",
                                 "The app counts the rows of every table before its data update and again after it, and marks this check by itself (it also shows at the top of To do). Run all automatic only tries the counting rule."], place: .noScooter),
        "a6": CheckGuide(proves: "The database opened and is up to date (data versioning).",
                         steps: ["Nothing to do: it marks itself at every launch."], place: .noScooter),
        "b1": CheckGuide(proves: "The app finds and connects to the scooter.",
                         steps: ["Switch the scooter on.", "Developer → Scooter.", "Wait about 10 s."], place: .scooterHome),
        "b2": CheckGuide(proves: "The scooter's data is decoded into sensible numbers.",
                         steps: ["Stay on Developer → Scooter with the scooter on for ~10 s."], place: .scooterHome),
        "b3": CheckGuide(proves: "The scooter's firmware is the one the decoder was built for.",
                         steps: ["Read automatically when the scooter connects."], place: .scooterHome),
        "b4": CheckGuide(proves: "The app only reads from the scooter: it never sends anything.",
                         steps: ["Read automatically when the scooter connects."], place: .scooterHome),
        "b5": CheckGuide(proves: "Whether the scooter reports a lock state.",
                         steps: ["Developer → Scooter → Lock: Record.", "Lock and unlock 3 times, ~5 s apart.",
                                 "Stop and check (or tap \"No lock on this scooter\")."], place: .scooterHome),
        "b8": CheckGuide(proves: "The Bluetooth link holds for 4 minutes with nothing happening (B04). The scooter switches itself off after ~5 min standing, so the test is 4 min.",
                         steps: ["iPhone Settings → Display & Brightness → Auto-Lock → Never (set it back afterwards).",
                                 "Scooter on, standing still.", "Developer → Scooter → Start 4-min test.",
                                 "Keep the phone UNLOCKED on this screen for the full 4 minutes: don't switch apps or lock it.",
                                 "The result shows at 4:00."], place: .scooterHome),
        "b9": CheckGuide(proves: "When the scooter goes out of range, the app reconnects by itself when you come back.",
                         steps: ["Scooter on. Developer → Scooter → Arm range test.", "Lock the phone.",
                                 "Walk 30–50 m away with the phone until the link drops (~1 min).",
                                 "Walk back to the scooter.", "Wait 30 s WITHOUT unlocking the phone.",
                                 "Then unlock and look at the result."], place: .scooterHome),
        "c1": CheckGuide(proves: "iOS wakes the app when the scooter turns on.",
