        "ui5": CheckGuide(proves: "The Places screen shows each place on a small map with its circle in its colour, and tapping a place opens a full map with its street name and its settings. Route cards and ride maps name their start and end place.",
                          steps: ["Settings (or Routes) → Places.", "Look at the small maps and the colour dots; tap a place: pin, circle, name, street name below, Rename, circle size, colour, I can charge here.", "Open a route card and a ride that ended at a place: the start and end carry the place name on a coloured pin.", "Tap Pass or Fail with a note."], place: .noScooter),
        "ui6": CheckGuide(proves: "You can add a place yourself: press and hold on the map, or search an address, then name, circle size and colour.",
                          steps: ["Places → + at the top right.", "Press and hold on the map: a pin and its circle appear. Or type an address and pick a suggestion.", "Name it, pick the circle and colour, tap Save place. It is in the Places list.", "Tap Pass or Fail with a note (does the long press work while you can still move the map?)."], place: .noScooter),
        "ui7": CheckGuide(proves: "Places have colours: Home green, Work blue, the rest in order, changeable on the place's map screen, and the Rides list shows a thin strip of the end place's colour on each row.",
                          steps: ["Open Places and a place: change its colour.", "Open Rides: rows that ended at that place show the strip in that colour; rows with no saved destination show a grey strip.", "Tap Pass or Fail with a note."], place: .noScooter),
        "u61": CheckGuide(proves: "The app's colours are the approved theme v2 in light and dark mode with readable contrast: orange only where it reads well (fills, icons, large numbers; a darker orange for small text), red and green kept for their meaning.",
